TOKEN_RE = re.compile(r"`[^`\n]+`|(?<![0-9a-f])[0-9a-f]{40}(?![0-9a-f])|(?<![0-9a-f])[0-9a-f]{64}(?![0-9a-f])|\b\d{4,}\b|\b[A-Z][A-Z0-9]+(?:-[A-Z0-9]+)+\b")

def atoms(text):
    return Counter(TOKEN_RE.findall(text))

changed = []
for rel in TARGETS:
    path = ROOT / rel
    before = path.read_text(encoding="utf-8")
    before_atoms = atoms(before)
    lines = before.splitlines(keepends=True)
    out=[]
    file_changed=False
    for line in lines:
        nl = "\n" if line.endswith("\n") else ""
        core = line[:-1] if nl else line
        if core in REPLACEMENTS:
            core = REPLACEMENTS[core]
            file_changed=True
        out.append(core+nl)
    after=''.join(out)
    if file_changed:
        if before_atoms != atoms(after):
            missing = before_atoms - atoms(after)
            added = atoms(after) - before_atoms
            raise SystemExit(f"canonical atom mismatch in {rel}: missing={missing} added={added}")
        path.write_text(after, encoding="utf-8")
        changed.append(rel)

if not changed:
    raise SystemExit("no Japanese documentation changes materialized")

remaining=[]
for rel in TARGETS:
    text=(ROOT/rel).read_text(encoding="utf-8")
    for old in REPLACEMENTS:
        if old in text.splitlines():
            remaining.append((rel,old))
if remaining:
    raise SystemExit(f"unreplaced audited lines remain: {remaining[:20]}")

print(f"localized {len(changed)} human-facing Markdown files")
for rel in changed:
    print(rel)
